import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Adds calendar months in UTC, keeping the time of day and clamping to the
 * target month's last day when it has no such day.
 */
export function addMonths(from: Date, months: number): Date {
  const total = from.getUTCFullYear() * 12 + from.getUTCMonth() + months;
  const year = Math.floor(total / 12);
  const month = total - year * 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const day = Math.min(from.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      from.getUTCHours(),
      from.getUTCMinutes(),
      from.getUTCSeconds(),
      from.getUTCMilliseconds(),
    ),
  );
}

/** The end of the period that starts at `start`. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addMonths(start, monthsIn(interval));
}

/** Plan price × seats × months, in cents. */
export function fullPeriodCharge(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsIn(interval);
}

/** Scales a full-period amount by the days left in the period, rounded down. */
export function prorate(
  fullAmountCents: number,
  periodStart: Date,
  periodEnd: Date,
  now: Date,
): number {
  const remainingMs = periodEnd.getTime() - now.getTime();
  const daysLeft = remainingMs <= 0 ? 0 : Math.ceil(remainingMs / MS_PER_DAY);
  const daysInPeriod = Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );
  return Math.floor((fullAmountCents * daysLeft) / daysInPeriod);
}
