  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;

  const cancelAt = new Date(subscription.cancelAt);
  if (cancelAt.getTime() > now.getTime()) return false;

  const orgId = subscription.orgId as OrgId;

  let start = cancelAt;
  let end = periodEndFor(start, "monthly");
